    tags: ["喘息服務", "長照3.0", "2026新制", "照顧者支持"],
    content: [
      { type: "p", text: "傳統喘息服務是一對一：居服員到你家、或長輩去機構短住。但 2026 年長照 3.0 上路後，衛福部推出了全新的「互助喘息服務試辦計畫」：由 1 名專業照顧服務員搭配 1 名家庭照顧者共同值班，一次照顧 4 到 12 位長輩；你去值班 1 次，家裡長輩就能獲得 2 次的喘息服務。這篇把「值一喘二」的規則、費用、據點和申請流程一次講清楚。" },
      { type: "h2", text: "一、互助喘息怎麼運作：「值一喘二」" },
      { type: "p", text: "互助喘息打破過去一對一的照顧模式。運作方式是：在假日借用日照中心的場地，由衛福部安排 1 名專業照顧服務員，搭配 1 名家庭照顧者擔任值班者，以「二對多」的方式共同照顧現場 4 至 12 名符合長照需要等級（CMS）2 至 8 級的被照顧者。" },
      { type: "ol", items: [
        "家庭照顧者到據點值班，最低 4 小時起跳",
        "值班 1 次，可兌換 2 次喘息：例如值班 4 小時，家中長輩就能在日照中心被照顧 8 小時",
        "被照顧者送到據點 4 小時，繳交 NT$100（長輩在現場的點心費）",
        "中低收入戶免費；從未使用過的家庭，可享 2 次免費體驗",
      ]},
      { type: "tip", text: "這個設計結合了「時間銀行」的概念：全家人都可以來值班、共同儲值時間，一年內即時交換、年底歸零。對人力吃緊的超高齡社會來說，這是一種把社區閒置場地和家庭照顧力活化起來的方法。" },
      { type: "h2", text: "二、互助喘息 vs 傳統喘息：差在哪" },
      { type: "table", headers: ["比較項目", "傳統喘息（居家／機構）", "互助喘息（試辦）"], rows: [
        ["照顧模式", "一對一（居服員到宅或長輩入住機構）", "二對多（照服員＋照顧者值班，4–12 位長輩）"],
        ["照顧者要做什麼", "把長輩交給專業人員，自己去休息", "先到據點值班 4 小時，再換 2 次喘息"],
        ["費用（被照顧者）", "依 CMS 等級與身分別，部分負擔 0–16%", "4 小時 NT$100 點心費；中低收免費"],
        ["服務時段", "平日為主，需事先排班", "假日為主，利用日照中心場地"],
        ["額度來源", "第四包喘息額度（年 32,340／48,510）", "試辦專案經費（總經費 2,500 萬元）"],
        ["適合對象", "所有符合資格的家庭", "有時間、有體力能值班的家庭照顧者"],
      ]},
      { type: "p", text: "特別提醒：試辦計畫另有專案經費，理論上不佔用你原本的第四包喘息額度。但各據點執行細節可能不同，預約時請直接向據點確認「會不會扣我的喘息額度」，避免認知落差。" },
      { type: "h2", text: "三、哪裡有據點：16 縣市 50 處，怎麼查" },
      { type: "p", text: "試辦計畫自 2026 年 3 月起跑，為期 1 年，目前在 16 個縣市布建 50 處服務據點（北、中、南、東都有）。例如屏東縣就有 5 處據點，包含原鄉與客庄的在地化模式。計畫目標是蒐集 1 年的實證資料，預計 3 年後（2029 年）正式納入長照給付上路。" },
      { type: "ol", items: [
        "在網路搜尋「互助喘息」，找到官方預約平台",
        "登入註冊帳號（未使用過的家庭可先預約 2 次免費體驗）",
        "選擇鄰近的據點與時段",
        "首次前往建議提早到：把長輩的作息、用藥、失智行為、移位需求先跟現場人員交接清楚",
      ]},
      { type: "info", text: "據點名單在試辦期間會持續增減，出發前務必上網確認最新名單與服務時段，不要憑印象跑一趟。若你住的縣市還沒有據點，仍可使用傳統的居家喘息或機構喘息（撥打 1966）。" },
      { type: "h2", text: "四、誰適合、誰不適合：誠實評估" },
      { type: "ul", items: [
        "適合：白天或假日能排出 4 小時的家庭照顧者；想認識其他照顧者、互相打氣的人；長輩能適應團體環境、喜歡熱鬧的人；需要「固定」假日喘息時段的上班族照顧者。",
        "不適合：已經耗盡體力、自己也快倒下的獨力照顧者；高齡配偶照顧者（自己也需要被照顧）；住得離據點很遠、交通不便的家庭；長輩有嚴重失智行為、會強烈抗拒陌生環境的人。",
      ]},
      { type: "warning", text: "沒辦法值班，不代表你沒有喘息的權利。互助喘息是「多一種選擇」，不是取代傳統喘息。體力已經見底的照顧者，請直接使用正式的居家喘息或機構喘息（第四包額度），不要硬撐去值班。" },
      { type: "h2", text: "五、值班當天要注意的事" },
      { type: "ul", items: [
        "現場一定有專業照顧服務員帶領，你不需要有照服員證照，負責協助陪伴、備餐、活動即可",
        "人數是 1 名照服員＋1 名值班照顧者顧 4–12 位長輩，遇到緊急狀況（跌倒、嗆咳、用藥）一律先找專業人員，不要自己處理",
        "把自家長輩的特殊需求寫成一張小卡交給現場人員：幾點吃藥、怎麼移位、失智時怎麼安撫",
        "值班也是一種學習：看別人怎麼處理進食、活動和情緒反應，是很多照顧者說最有收穫的部分",
      ]},
      { type: "tip", text: "還沒用過長照服務的家庭，建議先撥打 1966 做 CMS 評估、取得正式的喘息額度，再把互助喘息當作「加碼」的假日喘息選項，兩邊搭配使用效果最好。" },
    ],
    faq: [
      { q: "互助喘息跟一般的喘息服務最大的差別是什麼？", a: "傳統喘息是一對一、由專業人員全權照顧；互助喘息是二對多，家庭照顧者要先到據點值班（最低 4 小時），才能兌換 2 倍時數的喘息。它用「時間交換」代替「全額付費」，費用也極低（4 小時 100 元點心費）。" },
      { q: "去值班需要照顧專業或證照嗎？", a: "不需要。現場一定有 1 名專業照顧服務員帶領並負責安全與專業判斷，值班的家庭照顧者主要協助陪伴、備餐與活動。但建議先參加據點的新手說明，熟悉緊急狀況的通報流程。" },
      { q: "使用互助喘息會扣掉我的喘息額度嗎？", a: "試辦計畫另有專案經費（總經費 2,500 萬元），設計上不佔用第四包喘息額度。但各據點執行細節可能不同，預約時請直接向據點確認。" },
      { q: "試辦結束後會怎樣？以後還有嗎？", a: "目前試辦 1 年（2026 年 3 月起），衛福部要蒐集服務成效與實證資料再評估是否納入正式長照給付，目標是 3 年後（2029 年）正式上路。試辦期間的參與紀錄與回饋，會影響它能不能轉正。" },
    ],
