        "追溯自 2026 年 1 月 1 日起實施；9 月 14 日起開放申請新制。",
        "認列改為「按月認列」：當月實際入住達該月日曆天數一半以上，即認列 1 個月，不再需要全年累積住滿 180 天。",
        "撥款一年 2 次：地方政府按上、下半年分 2 次檢核撥付，縮短補助到位時間。",
        "2026 年過渡保障：2025 年度已核定領取 12 萬者，2026 年 1–8 月累積住滿 180 天，該期間一律核給 12 萬；9 月起再依新制按月認列。",
        "身心障礙者住宿式照顧費用補助，每月也提高 NT$5,000；已核定領取身障住宿照顧補助、且持有中度以上證明者，原制不變、另可申請每月 NT$5,000 住宿費用補助。",
        "預算編列 NT$166.17 億，預計約 10.5 萬名機構住民受惠；取消排富（2023 年起即取消）。",
