        "誤區二：額度可以挪去請居服員。錯：四包錢各有用途，交通額度不能轉到第一包照顧服務。",
        "誤區三：偏鄉額度高是優惠。不是優惠，是成本反映：偏鄉一趟路程長、單價高，額度高才夠用。",
        "誤區四：叫一般計程車、拿收據就能報。錯：必須是照顧計畫核定、特約單位派車的行程才算。",
